const debug = createInlineDebugLogger('close-modal');

const trackRemovedPage = async (page: Page) => {
    // eslint-disable-next-line no-underscore-dangle
    await getCurrentSync().Browser.wrapSync(currentOFIdentity)._trackRemovedTab({ identity: currentOFIdentity, page });
};
const trackRemovedWindow = async () => {
    const w = getCurrentOFWindow();
    const options = await w.getOptions();
    if (options.workspacePlatform) {
        // eslint-disable-next-line no-underscore-dangle
        await getCurrentSync()
            .Browser.wrapSync(currentOFIdentity)
            ._trackRemovedTab({ window: options.workspacePlatform });
    }
};

const raiseBrowserModalAnalytics = (action: string, type: 'Page Modal' | 'Window Modal', value: string, data?: any) =>
    raiseBrowserAnalytics({
        type: type,
        action: action,
        value: value,
        skipValueHashing: true,
        data
    });

const raisePageModalAnalytics = (action: string, value: string, data?: any) =>
    raiseBrowserModalAnalytics(action, 'Page Modal', value, data);

const raiseWindowModalAnalytics = (action: string, value: string, data?: any) =>
    raiseBrowserModalAnalytics(action, 'Window Modal', value, data);

/**
 * Sets the targeted page as active and displays a modal dialog to confirm the closure of the page.
 * If the page has never been saved before, it prompts the user to enter a title for the page to save.
 *
 * @param {Object} params - The parameters for the function.
 * @param {AttachedPage} params.page - The page to be closed.
 * @param {boolean} params.isSaved - Indicates if the page is already saved.
 * @param {string} [params.titlePrefix] - Optional prefix for the title in the modal dialog.
 *
 * @returns {Promise<ModalResponse>} - A promise that resolves to the response from the modal dialog.
 */
const showClosePageModal = async ({
    page,
    isSaved,
    titlePrefix
}: {
    page: AttachedPage;
    isSaved: boolean;
    titlePrefix?: string;
}) => {
    const textInputOptions = isSaved
        ? null
        : { placeholder: 'Please enter a title of the page to save', defaultValue: page.title };
    const { windowOptions, content, parameters } = await getPageCloseMenu({
        textInputOptions,
        titlePrefix
    });

    // Set the target page active so users have context on the page they're closing
    const browser = getCurrentSync().Browser.wrapSync(currentOFIdentity);
    await browser.setActivePage(page.pageId);

    const { top, left } = await getResponseModalBoundsAndCenterParentIfModalOffScreen(windowOptions, currentOFIdentity);
    const pageCloseOptions = { ...windowOptions, top, left };

    return waitForModalResponse({
        options: pageCloseOptions,
        content,
        parameters
    });
};

/**
 * Conditionally await a function based on a shouldAwait flag
 * If shouldAwait is true, the function will be awaited and return the result of the function
 *   Otherwise, the function will be called and return Promise<void>
 *
 * @param fn the async function to conditionally await
 * @param shouldAwait whether to await the function
 */
const conditionallyAwaitFunction = async <T>(fn: () => Promise<T>, shouldAwait: boolean): Promise<T | void> => {
    if (shouldAwait) {
        return fn();
    } else {
        // Intentionally not awaiting the function
        fn();
    }
};

/**
 * Handles the shared modal response actions (close-button, Cancel, Discard Changes) that are
 * common across both the standard close-page and publish-on-close flows.
 *
 * @returns true if the action was fully handled, false if the caller should handle it (e.g. Save, Publish).
 */
const handleCommonModalResponse = async ({
    actionName,
    pageId,
    pageTitle,
    recentlyActivePageId,
    awaitAnalytics,
    skipPageClose
}: {
    actionName: string;
    pageId: string;
    pageTitle: string;
    recentlyActivePageId?: string;
    awaitAnalytics?: boolean;
    skipPageClose?: boolean;
}): Promise<boolean> => {
    const browser = getCurrentSync().Browser.wrapSync(currentOFIdentity);

    switch (actionName) {
        case 'close-button':
            await conditionallyAwaitFunction(() => raisePageModalAnalytics('Select Close', pageTitle), awaitAnalytics);
            return true;
        case 'Cancel':
            raisePageModalAnalytics('Select Cancel', pageTitle);
            return true;
        case 'Discard Changes':
            await conditionallyAwaitFunction(
                () => raisePageModalAnalytics('Select Discard Changes', pageTitle),
                awaitAnalytics
            );
            if (!skipPageClose) {
                if (recentlyActivePageId && pageId !== recentlyActivePageId) {
                    debug('discard: switching active page before removal', { from: pageId, to: recentlyActivePageId });
                    await browser.setActivePage(recentlyActivePageId);
                }
                debug('discard: removing page', { pageId });
                await browser.removePage(pageId);
                debug('discard: page removed', { pageId });
            }
            return true;
        default:
            return false;
    }
};

const handleClosePageModalResponse = async ({
    response,
    pageId,
    recentlyActivePageId,
    pageTitle,
    awaitAnalytics,
    skipPageClose
}: {
    response: Awaited<ReturnType<typeof showClosePageModal>>;
    pageId: string;
    pageTitle: string;
    recentlyActivePageId?: string;
    awaitAnalytics?: boolean;
    skipPageClose?: boolean;
}) => {
    const handled = await handleCommonModalResponse({
        actionName: response.data.actionName,
        pageId,
        pageTitle,
        recentlyActivePageId,
        awaitAnalytics,
        skipPageClose
    });

    if (handled) return;

    if (response.data.actionName === 'Save') {
        const platform = getCurrentSync();
        const browser = platform.Browser.wrapSync(currentOFIdentity);

        try {
            const newTitle = response.data.data?.textInputValue;
            debug('save: updating page', { pageId, newTitle });
            await browser.updatePage({
                pageId: pageId,
                page: { title: newTitle, hasUnsavedChanges: false }
            });
            const pageToSave = await browser.getPage(pageId);
            const analyticsVerb = (await platform.Storage.getPage(pageId)) ? 'Save' : 'Save As';

            await platform.Storage.savePage(pageToSave);

            await conditionallyAwaitFunction(
                () => raisePageModalAnalytics(`Select ${analyticsVerb}`, pageToSave.title),
                awaitAnalytics
            );

            if (!skipPageClose) {
                await showSuccess({
                    message: t('enterpriseSuccessIndicator.supertabSaved'),
                    parentBrowserName: browser.identity.name,
                    secondaryMessage: t('enterpriseSuccessIndicator.supertabHasBeenSaved', {
                        title: pageToSave.title
                    }),
                    isEnterprise: true
                });

                if (recentlyActivePageId && pageId !== recentlyActivePageId) {
                    debug('save: switching active page before removal', { from: pageId, to: recentlyActivePageId });
                    await browser.setActivePage(recentlyActivePageId);
                }

                debug('save: removing page', { pageId });
                await browser.removePage(pageId);
                debug('save: page removed', { pageId });
            }
        } catch (err) {
            logger.error('handleClosePageModalResponse', 'Failed to save a page', {
                pageId,
                error: err instanceof Error ? err.message : String(err),
                stack: err instanceof Error ? err.stack : undefined
            });
            await showError({
                message: 'Failed to save a page',
                parentBrowserName: browser.identity.name
            });
        }
    }
};

const shouldShowUnsavedPageModal = (payload: HandleSaveModalOnPageClosePayload) => {
    // In EB, high-level tabs shouldn't prompt about unsaved changes
    if (countViews(payload.page.layout.content) === 1) {
        logger.debug('shouldShowUnsavedPageModal', 'Skipping save modal for single-view page in Enterprise browser', {
            pageId: payload.page.pageId,
            identity: payload.identity
        });
        return { shouldShowModal: false };
    }
    // By default, only show modal if there are unsaved changes to the page.
    return { shouldShowModal: !!payload.page.hasUnsavedChanges };
};

const handlePublishedPageClose = async ({
    page,
    recentlyActivePageId,
    isLastPage
}: {
    page: AttachedPage;
    recentlyActivePageId?: string;
    isLastPage: boolean;
}) => {
    const platform = getCurrentSync();
    const browser = platform.Browser.wrapSync(currentOFIdentity);

    await browser.setActivePage(page.pageId);

    const response = await showPublishOnCloseModal(currentOFIdentity);

    const handled = await handleCommonModalResponse({
        actionName: response.data.actionName,
        pageId: page.pageId,
        pageTitle: page.title,
        recentlyActivePageId,
        awaitAnalytics: isLastPage
    });

    if (handled) return;

    if (response.data.actionName === 'Publish') {
        try {
            // eslint-disable-next-line no-underscore-dangle
            const published = await platform._invokeCustomAction('publish-page-on-close', {
                windowIdentity: currentOFIdentity
            } as any);

            if (!published) {
                return;
            }

            await conditionallyAwaitFunction(() => raisePageModalAnalytics('Select Publish', page.title), isLastPage);

            if (recentlyActivePageId && page.pageId !== recentlyActivePageId) {
                await browser.setActivePage(recentlyActivePageId);
            }
            await browser.removePage(page.pageId);
        } catch (err) {
            logger.error('handlePublishPage', 'Failed to publish page on close', { error: err });
            await showError({
                message: 'Failed to publish page',
                parentBrowserName: browser.identity.name
            });
        }
    }
};

export interface ClosePageRequestPayload {
    pageId: string;
    closeType?: 'page' | 'view';
}
export const handleClosePageRequest = createAsyncThunk<void, ClosePageRequestPayload>(
    'pages/handleClosePageRequest',
    async ({ pageId, closeType }: ClosePageRequestPayload, { getState }) => {
        // Make sure page passed into overrides has latest layout
        await updateInternalPageState();

        const pages = selectPages(getState() as AttachedPagesRootState);
        const targetPage = pages.find((page) => page.pageId === pageId);
        const browser = getCurrentSync().Browser.wrapSync(currentOFIdentity);

        const { shouldPageClose } = await requestShouldPageClose({
            closeType: closeType || 'page',
            page: targetPage,
            identity: currentOFIdentity
        });
        if (!shouldPageClose) {
            logger.debug('handleClosePageRequest', 'Closing of page prevented by shouldPageClose override', { pageId });
            return;
        }

        await trackRemovedPage(targetPage);

        const { shouldShowModal } = await shouldShowUnsavedPageModal({
            page: targetPage,
            identity: currentOFIdentity
        });
        if (!shouldShowModal) {
            await browser.removePage(pageId);
            return;
        }

        const recentlyActivePageId = pages.find((page) => page.isActive)?.pageId;

        if (targetPage.isPublished) {
            await handlePublishedPageClose({
                page: targetPage,
                recentlyActivePageId,
                isLastPage: pages.length === 1
            });
            return;
        }

        const savedPage = await getCurrentSync().Storage.getPage(pageId);
        // Set the target page active and pop a modal prompting user to save the page
        const response = await showClosePageModal({ page: targetPage, isSaved: !!savedPage });

        const isLastPage = pages.length === 1;
        await handleClosePageModalResponse({
            response,
            pageId: targetPage.pageId,
            recentlyActivePageId,
            pageTitle: targetPage.title,
            awaitAnalytics: isLastPage
        });
    }
);

/*
 * Get the pages that have unsaved changes and show the modal to save them
 */
const getPagesToSave = async (browserPages: AttachedPageInternal[]): Promise<AttachedPageInternal[]> => {
    const unsavedPages = browserPages.filter(({ hasUnsavedChanges }) => hasUnsavedChanges);
    // array of true/false indicating if modal should be shown for the page
    const isPageSavable: boolean[] = await Promise.all(
        unsavedPages.map(async (page) => {
            const { shouldShowModal } = await shouldShowUnsavedPageModal({
                page: page,
                identity: currentOFIdentity
            });
            return shouldShowModal;
        })
    );
    return unsavedPages.filter((_page, index) => isPageSavable[index]) as AttachedPageInternal[];
};

/*
 * Check if the page has been saved before
 */
const hasPageBeenSavedBefore = (storagePage: Page[], page: AttachedPageInternal): boolean =>
    storagePage.some((storedPage) => storedPage.pageId === page.pageId);

/*
 * Categorize pages into previously saved and never saved
 */
const categorizePagesBySaveStatus = (
    savablePages: AttachedPage[],
    pagesInStorage: Page[]
): {
    previouslySavedPages: AttachedPage[];
    neverSavedPages: AttachedPage[];
} => {
    return savablePages.reduce(
        (accum, page) => {
            hasPageBeenSavedBefore(pagesInStorage, page)
                ? accum.previouslySavedPages.push(page)
                : accum.neverSavedPages.push(page);
            return accum;
        },
        { previouslySavedPages: [] as AttachedPage[], neverSavedPages: [] as AttachedPage[] }
    );
};

const savePreviouslySavedPages = async (previouslySavedPages: AttachedPage[], browser: BrowserWindowModule) => {
    for (let i = 0; i < previouslySavedPages.length; i++) {
        const page = previouslySavedPages[i];

        // if page is active, fetch it using API to get the up-to-date layout
        const pageToSave = page.isActive ? await browser.getPage(page.pageId) : page;

        await getCurrentSync().Storage.savePage(cleanPage(pageToSave));
        await browser.updatePage({
            pageId: pageToSave.pageId,
            page: {
                hasUnsavedChanges: false
            }
        });
    }
};

/*
 * Handle the unsaved pages modals.
 * Returns true if all page save modals were handled gracefully.
 * Returns false if one of the page save modals is aborted.
 */
const handleUnsavedPagesWithRenameModals = async (neverSavedPages: AttachedPage[]) => {
    const pages = await getPages(currentOFIdentity);
    const recentlyActivePageId = pages.find((page) => page.isActive).pageId;
    const skipPageClose = neverSavedPages.length > 1;

    for (let index = 0; index < neverSavedPages.length; ++index) {
        const page = neverSavedPages[index];
        const modalResponse = await showClosePageModal({
            page,
            isSaved: false,
            titlePrefix: neverSavedPages.length > 1 && `(${index + 1}/${neverSavedPages.length}) `
        });
        await handleClosePageModalResponse({
            response: modalResponse,
            pageId: page.pageId,
            recentlyActivePageId,
            pageTitle: page.title,
            awaitAnalytics: true,
            skipPageClose
        });

        if (modalResponse.data.actionName === 'Cancel' || modalResponse.data.actionName === 'close-button') {
            return false;
        }
    }
    return true;
};

export const closeBrowserWindow = async () => {
    const currentWindow = getCurrentOFWindow();
    await trackRemovedWindow();
    await currentWindow.close(true);
};

/**
 * Show the close window modal
 */
export const handleCloseWindowRequest = createAsyncThunk<void>('pages/handleCloseWindowRequest', async () => {
    await trackRemovedWindow();

    // use getPages here instead of redux store to get latest layout for active page
    const browserPages = await getPages(currentOFIdentity);
    const platform = getCurrentSync();
    const { shouldWindowClose } = await requestShouldWindowClose({
        pages: browserPages,
        identity: currentOFIdentity
    });

    if (!shouldWindowClose) {
        logger.debug(
            'handleCloseWindowRequest',
            'Closing of the window prevented by handlePagesAndWindowClose override',
            {
                windowIdentity: currentOFIdentity
            }
        );
        return;
    }
    const savablePages = await getPagesToSave(browserPages);
    const pagesInStorage = await platform.Storage.getPages();
    const { previouslySavedPages, neverSavedPages } = categorizePagesBySaveStatus(savablePages, pagesInStorage);

    if (savablePages.length === 0) {
        // Do not show modal if there are no unsaved pages.
        await closeBrowserWindow();
        return;
    }

    // When closing from taskbar, need to focus to prevent immediate blur of the response modal
    await fin.me.focus();

    if (previouslySavedPages.length === 0 && neverSavedPages.length === 1) {
        // If there is only one unsaved page that was not saved before, only show the save changes modal for that page
        const allSavePageModalsHandled = await handleUnsavedPagesWithRenameModals(neverSavedPages);

        if (allSavePageModalsHandled) {
            await closeBrowserWindow();
        }
        return;
    }

    const { windowOptions, content, parameters } = await getBrowserWindowCloseMenu({
        unsavedPagesCount: savablePages.length
    });
    const { top, left } = await getResponseModalBoundsAndCenterParentIfModalOffScreen(windowOptions, currentOFIdentity);

    const browserWindowCloseOptions = { ...windowOptions, top, left };

    const response = await waitForModalResponse({
        options: browserWindowCloseOptions,
        content,
        parameters
    });

    switch (response.data.actionName) {
        case 'close-button':
            await raiseWindowModalAnalytics('Select Close', currentOFIdentity.name);
            break;
        case 'Save All': {
            // save the pages
            const browser = platform.Browser.wrapSync(currentOFIdentity);
            let allSavePageModalsHandled = true;

            if (previouslySavedPages.length > 0) {
                await savePreviouslySavedPages(previouslySavedPages, browser);
            }

            if (neverSavedPages.length) {
                allSavePageModalsHandled = await handleUnsavedPagesWithRenameModals(neverSavedPages);
            }

            await raiseWindowModalAnalytics('Select Save All', currentOFIdentity.name);

            if (allSavePageModalsHandled) {
                await closeBrowserWindow();
            }
            break;
        }
        case 'Discard All': {
            await raiseWindowModalAnalytics('Select Discard All', currentOFIdentity.name);
            await closeBrowserWindow();
            break;
        }
        case 'Cancel':
            // Not closing, do not need to await analytics
            raiseWindowModalAnalytics('Select Cancel', currentOFIdentity.name, {
                uuid: currentOFIdentity.uuid
            });
    }
});
