import { PageLayout } from '@common/api/pages/shapes';

export type EnterprisePageRequiredLayoutSettings = {
    newTabButtonUrl: string;
};

/**
 * Applies required layout settings for enterprise pages.
 * Always sets the newTabButton URL to ensure pages from storage or other sources
 * have the correct landing page URL.
 */
export const applyEnterprisePageRequiredLayoutSettings = (
    requiredSettings: EnterprisePageRequiredLayoutSettings,
    layout: PageLayout
) => {
    if (!layout.settings) {
        layout.settings = {};
    }

    // Always set the correct newTabButton URL to ensure pages from storage
    // or external sources have the correct landing page URL (undocumented container setting...)
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore
    layout.settings.newTabButton = { url: requiredSettings.newTabButtonUrl };
};
