import type OpenFin from '@openfin/core';

import { isOSWindows } from '@common/utils/os';
import { raiseBrowserAnalytics } from '@common/utils/usage-register';

import { copyObject } from '@client-platform/init/utils';
import {
    BrowserCreateViewRequest,
    BrowserViewState,
    BrowserWorkspacePlatformViewOptions,
    BrowserWorkspacePlatformWindowOptions
} from '@client-platform/shapes';

export async function preserveInteropIfManifestConflict(
    opts: Partial<OpenFin.ViewOptions>,
    fetchManifest: ({ manifestUrl }: { manifestUrl: string }, callerIdentity: OpenFin.Identity) => any,
    callerIdentity: OpenFin.Identity
) {
    // TODO - This is a less than ideal series of code :) that should be fixed by the container team JIRA - https://openfin.jira.com/browse/RUN-7554
    const manifestOpts = opts.manifestUrl
        ? await fetchManifest({ manifestUrl: opts.manifestUrl }, callerIdentity)
        : undefined;
    if (manifestOpts?.interop && opts.interop) {
        const preservedOpts = {
            ...opts,
            ...manifestOpts,
            interop: opts.interop
        };
        delete preservedOpts.manifestUrl;
        return preservedOpts;
    }
    return opts;
}

type ViewStateBase = Pick<BrowserViewState, '_internalWorkspaceData' | 'workspacePlatform'>;

export const mapInternalWorkspaceDataToWorkspacePlatform = <T extends ViewStateBase>(viewState: T): T => {
    const newState = copyObject(viewState);

    if (newState._internalWorkspaceData?.browserNavigationButtons) {
        newState.workspacePlatform = {
            ...newState.workspacePlatform,
            browserNavigationButtons: newState._internalWorkspaceData.browserNavigationButtons
        };
        delete newState._internalWorkspaceData.browserNavigationButtons;
    }
    return newState;
};

export const mapWorkspacePlatformToInternalWorkspaceData = <T extends ViewStateBase>(viewState: T): T => {
    const newState = copyObject(viewState);

    if (newState.workspacePlatform) {
        newState._internalWorkspaceData = {
            ...newState._internalWorkspaceData,
            ...newState.workspacePlatform
        };
        delete newState.workspacePlatform;
    }
    return newState;
};

const hotkeyMapWin = {
    reload: [{ keys: 'Ctrl+R', preventDefault: true }],
    back: [{ keys: 'Alt+Left', preventDefault: true }],
    forward: [{ keys: 'Alt+Right', preventDefault: true }]
};

const hotkeyMapMac = {
    reload: [{ keys: 'Cmd+R', preventDefault: true }],
    back: [
        { keys: 'Cmd+[', preventDefault: true },
        { keys: 'Cmd+Left', preventDefault: true }
    ],
    forward: [
        { keys: 'Cmd+]', preventDefault: true },
        { keys: 'Cmd+Right', preventDefault: true }
    ]
};

const getHotkeyMap = async () => {
    const isWindows = await isOSWindows();
    return isWindows ? hotkeyMapWin : hotkeyMapMac;
};

export const setHotkeysIfNavigationButtonsEnabled = async (options: BrowserCreateViewRequest) => {
    const newOptions = copyObject(options);
    const btnOptions = newOptions.workspacePlatform?.browserNavigationButtons;

    if (btnOptions) {
        const btnOptionsKeys = Object.keys(btnOptions) as (keyof typeof btnOptions)[];
        for (const btnKey of btnOptionsKeys) {
            if (btnOptions[btnKey]) {
                const hotkeyMap = await getHotkeyMap();
                const hotkeys = hotkeyMap[btnKey];
                if (newOptions.hotkeys) {
                    newOptions.hotkeys.push(...hotkeys);
                } else {
                    newOptions.hotkeys = [...hotkeys];
                }
            }
        }
    }
    return newOptions;
};

type ExtendedHotkeyEvent = OpenFin.Events.ViewEvents.HotkeyEvent & {
    altKey: boolean;
    ctrlKey: boolean;
    metaKey: boolean;
    shiftKey: boolean;
    inputType: 'keyUp' | 'keyDown';
    key: string;
};

const areHotkeysOnWindowEnabled = async (view: OpenFin.View): Promise<boolean> => {
    const currentWindow = await view.getCurrentWindow();
    const currentWindowOptions = await currentWindow.getOptions();
    const navigationButtons = (currentWindowOptions.workspacePlatform as BrowserWorkspacePlatformWindowOptions)
        ?.navigationButtons;
    return navigationButtons.enabled && !navigationButtons.hotkeysDisabled;
};
const handleHotkeyEvent = async (
    viewInstance: OpenFin.View,
    buttonOptions: BrowserWorkspacePlatformViewOptions['browserNavigationButtons'] | undefined,
    event: ExtendedHotkeyEvent
) => {
    if (event.inputType !== 'keyDown') {
        return;
    }

    const hotkeysOnWindowEnabled = await areHotkeysOnWindowEnabled(viewInstance);
    const isWindows = await isOSWindows();

    if (!hotkeysOnWindowEnabled) {
        return;
    }

    if (buttonOptions.reload) {
        const isCtrlR = event.ctrlKey && !event.altKey && !event.metaKey && !event.shiftKey && event.key === 'r';
        const isCmdR = !event.ctrlKey && !event.altKey && event.metaKey && !event.shiftKey && event.key === 'r';
        if ((isWindows ? isCtrlR : isCmdR) && buttonOptions?.reload) {
            viewInstance.reload();
            raiseBrowserAnalytics({ type: 'View', action: 'Reload', value: viewInstance.identity.name });
        }
    }

    if (buttonOptions.back) {
        const isAltLeft =
            !event.ctrlKey && event.altKey && !event.metaKey && !event.shiftKey && event.key === 'ArrowLeft';
        const isCmdLeft =
            !event.ctrlKey && !event.altKey && event.metaKey && !event.shiftKey && event.key === 'ArrowLeft';
        const isCmdLeftBracket =
            !event.ctrlKey && !event.altKey && event.metaKey && !event.shiftKey && event.key === '[';
        if ((isWindows ? isAltLeft : isCmdLeft || isCmdLeftBracket) && buttonOptions?.back) {
            viewInstance.navigateBack();
            raiseBrowserAnalytics({ type: 'View', action: 'Back', value: viewInstance.identity.name });
        }
    }

    if (buttonOptions.forward) {
        const isAltRight =
            !event.ctrlKey && event.altKey && !event.metaKey && !event.shiftKey && event.key === 'ArrowRight';
        const isCmdRight =
            !event.ctrlKey && !event.altKey && event.metaKey && !event.shiftKey && event.key === 'ArrowRight';
        const isCmdRightBracket =
            !event.ctrlKey && !event.altKey && event.metaKey && !event.shiftKey && event.key === ']';
        if ((isWindows ? isAltRight : isCmdRight || isCmdRightBracket) && buttonOptions?.forward) {
            viewInstance.navigateForward();
            raiseBrowserAnalytics({ type: 'View', action: 'Forward', value: viewInstance.identity.name });
        }
    }
};

export const registerHotkeyListenersIfEnabled = (
    viewIdentity: OpenFin.Identity,
    buttonOptions?: BrowserWorkspacePlatformViewOptions['browserNavigationButtons']
) => {
    const viewInstance = fin.View.wrapSync(viewIdentity);

    if (!buttonOptions) {
        return;
    }

    const hotkeyListener = (event: ExtendedHotkeyEvent) => {
        handleHotkeyEvent(viewInstance, buttonOptions, event);
    };

    viewInstance.addListener('hotkey', hotkeyListener);

    viewInstance.once('destroyed', () => {
        viewInstance.removeListener('hotkey', hotkeyListener);
    });
};
