import type OpenFin from '@openfin/core';

import { finUUID } from '@common/utils/env';
import { createLogger } from '@common/utils/logger';
import { handleViewHotkey } from '@common/utils/hotkeys';
import { currentOFIdentity } from '@common/utils/window';

import {
    ExtendedPanelConfig,
    PanelConfigHorizontal,
    PanelConfigVertical,
    PanelPosition
} from '@common/api/pages/shapes';

import { selectActivePage, selectActivePageIndex, updatePageAtIndex } from '@enterprise/slices/pages/attached';

import { getSizeWithoutCSSUnits } from '@enterprise/components/PanelContainer/PanelContainer';

import { dispatch, getState } from './pages/state';

const logger = createLogger('enterprise.panels');

const resizeObserverDisconnectCallbacks = new Map<string, () => void>();

const isPanelZeroSized = (panelConfig: ExtendedPanelConfig) => {
    const primaryDimension = [PanelPosition.Left, PanelPosition.Right].includes(panelConfig.position)
        ? (panelConfig as PanelConfigVertical).width
        : (panelConfig as PanelConfigHorizontal).height;
    return getSizeWithoutCSSUnits(primaryDimension) === 0;
};

export async function attachPanelViews(panels: ExtendedPanelConfig[] = []) {
    const panelInitPromises = panels.map(async (panelConfig) => {
        const view = fin.View.wrapSync({ name: panelConfig.viewOptions.name, uuid: fin.me.uuid });
        await view.attach(fin.me.identity);

        if (isPanelZeroSized(panelConfig)) {
            await view.hide();
        } else {
            await view.show();
        }

        const panelElement = document.getElementById('panel' + panelConfig.position);
        const disconnectCallback = await view.bindToElement(panelElement);
        resizeObserverDisconnectCallbacks.set(panelConfig.viewOptions.name, disconnectCallback);

        view.addListener('hotkey', handleViewHotkey);
    });
    await Promise.all(panelInitPromises);
}

export async function setUpPanelViews(panels: ExtendedPanelConfig[] = [], panelsToReplace: ExtendedPanelConfig[] = []) {
    for (const disconnectCallback of resizeObserverDisconnectCallbacks.values()) {
        disconnectCallback();
    }
    resizeObserverDisconnectCallbacks.clear();

    await attachPanelViews(panels);

    const viewDetachPromises = panelsToReplace.map(async (oldPanel) => {
        if (!panels.find((newPanel) => newPanel.viewOptions.name === oldPanel.viewOptions.name)) {
            // Attach view that's no longer needed to platform window for cleanup
            const view = fin.View.wrapSync(oldPanel.viewOptions);
            await view.attach({ name: currentOFIdentity.uuid, uuid: currentOFIdentity.uuid });
            await view.hide();
        }
    });
    await Promise.all(viewDetachPromises);
}

export async function getPanelsWithViewSnapshots(panels: ExtendedPanelConfig[] = []) {
    return Promise.all(
        panels.map(async (panel) => {
            const platform = fin.Platform.getCurrentSync();
            const snapshotViewOpts = await platform.getViewSnapshot(panel.viewOptions);
            return { ...panel, viewOptions: { ...snapshotViewOpts, uuid: finUUID } };
        })
    );
}

export const handlePanelViewDetached = async (e: OpenFin.WindowEvents.ViewDetachedEvent) => {
    // View attached to another browser, not platform provider
    // Target is sometimes `null` if a view is destroyed
    if (e.target?.name !== fin.me.uuid) {
        const view = fin.View.wrapSync(e.viewIdentity);
        const state = getState();
        const activePage = selectActivePage(state);
        const activePageIndex = selectActivePageIndex(state);

        // remove panel config if view of the panel is grabbed by another browser window
        const filteredPanels = activePage.panels?.filter((panel: ExtendedPanelConfig) => {
            const isViewIdentityMatching = panel.viewOptions.name === e.viewIdentity.name;
            if (isViewIdentityMatching) {
                const disconnectCallback = resizeObserverDisconnectCallbacks.get(panel.viewOptions.name);
                disconnectCallback();
                resizeObserverDisconnectCallbacks.delete(panel.viewOptions.name);
            }
            return !isViewIdentityMatching;
        }) as ExtendedPanelConfig[];

        try {
            await view.removeListener('hotkey', handleViewHotkey);
        } catch (error) {
            logger.error('handleViewDetached', 'Failed to remove hotkey listener for view', {
                viewName: e.viewIdentity.name,
                error
            });
        }

        dispatch(
            updatePageAtIndex({
                index: activePageIndex,
                page: { ...activePage, panels: filteredPanels }
            })
        );
    }
};
